  @Nested
  @DisplayName("redirect default-port normalization")
  class RedirectDefaultPortNormalization {

    /*
     * Regression: same-origin check on redirect previously compared raw
     * URI.getPort() values, so a redirect from `https://host/x` (port -1)
     * to `https://host:443/y` (port 443) was treated as cross-origin and
     * the Authorization header was stripped. effectivePort(...) normalizes
     * the omitted port to the scheme's default so the two URIs compare
     * equal and credentials survive the hop.
     */
    @Test
    @DisplayName("bhvRedirects037 redirect_to_explicit_default_port_preserves_authorization")
    void bhvRedirects037RedirectToExplicitDefaultPortPreservesAuthorization() throws Exception {
      java.lang.reflect.Method method =
          DefaultApiClient.class.getDeclaredMethod("effectivePort", java.net.URI.class);
      method.setAccessible(true);

      int httpsImplicit = (int) method.invoke(null, java.net.URI.create("https://host/x"));
      int httpsExplicit = (int) method.invoke(null, java.net.URI.create("https://host:443/y"));
      int httpImplicit = (int) method.invoke(null, java.net.URI.create("http://host/x"));
      int httpExplicit = (int) method.invoke(null, java.net.URI.create("http://host:80/y"));
      int httpsCustom = (int) method.invoke(null, java.net.URI.create("https://host:8443/y"));

      assertEquals(443, httpsImplicit, "implicit https port must normalize to 443");
      assertEquals(443, httpsExplicit, "explicit :443 must round-trip as 443");
      assertEquals(80, httpImplicit, "implicit http port must normalize to 80");
      assertEquals(80, httpExplicit, "explicit :80 must round-trip as 80");
      assertEquals(8443, httpsCustom, "non-default ports must round-trip unchanged");
    }

    /*
     * Security regression: a 30x from `https://host/x` to `http://host/x`
     * is a TLS downgrade; the Authorization (and other sensitive) headers
     * MUST be stripped on the follow-up. Previously sameOrigin() only
     * compared host + port and so happily forwarded the Authorization
     * over plain HTTP. This unit test verifies that sameOrigin() now
     * rejects redirects that change the scheme even when host + port
     * line up (e.g. a server that listens on the same port for both
     * schemes — uncommon but legal).
     */
    @Test
    @DisplayName("https_to_http_same_host_strips_authorization")
    void bhvRedirects053HttpsToHttpSameHostStripsAuthorization() throws Exception {
      java.lang.reflect.Method method =
          DefaultApiClient.class.getDeclaredMethod(
              "sameOrigin", java.net.URI.class, java.net.URI.class);
      method.setAccessible(true);

      boolean httpsToHttp =
          (boolean)
              method.invoke(
                  null,
                  java.net.URI.create("https://host:8443/x"),
                  java.net.URI.create("http://host:8443/y"));
      boolean httpToHttps =
          (boolean)
              method.invoke(
                  null,
                  java.net.URI.create("http://host:8080/x"),
                  java.net.URI.create("https://host:8080/y"));
      boolean sameScheme =
          (boolean)
              method.invoke(
                  null,
                  java.net.URI.create("https://host:8443/x"),
                  java.net.URI.create("https://host:8443/y"));
      boolean sameSchemeImplicitPort =
          (boolean)
              method.invoke(
                  null,
                  java.net.URI.create("https://host/x"),
                  java.net.URI.create("https://host:443/y"));

      assertFalse(httpsToHttp, "https→http redirect MUST be cross-origin (TLS downgrade)");
      assertFalse(httpToHttps, "http→https redirect MUST be cross-origin (scheme changes)");
      assertTrue(sameScheme, "same-scheme same-host same-port must be same-origin");
      assertTrue(sameSchemeImplicitPort, "implicit default port must compare equal to explicit");
    }
  }

  @Nested
  @DisplayName("redirect body-replay status guard (Gap N1)")
  class RedirectBodyReplayStatusGuard {

    /*
     * Gap N1: the HTTPS->HTTP body-replay refusal must be guarded ONLY on
     * 307/308 (the statuses that actually carry the body forward). On a 302
     * HTTPS->HTTP redirect carrying a body the request proceeds — per RFC
     * the follow-up becomes GET and the body is dropped, so there is no
     * cleartext body to leak and the client must NOT throw. node was the
     * divergent SDK (it refused on every status); the other 11, Java
     * included, guard 307/308 only. Asserted directly against the predicate
     * so the exact status matrix is locked.
     */
    @Test
    @DisplayName("bhvRedirects001 302_307_308_https_to_http_with_body_throw")
    void bhvRedirects001Redirect302307And308ThrowWithBody() {
      java.net.URI origin = java.net.URI.create("https://api.example.com/secret");
      java.net.URI target = java.net.URI.create("http://api.example.com/landed");

      // 302 HTTPS->HTTP with a body: must be refused like 307 and 308 (the body
      // would otherwise be replayed in cleartext).
      assertTrue(
          DefaultApiClient.shouldRefuseHttpsToHttpBodyReplay(origin, target, 302, true),
          "302 HTTPS->HTTP with body must be refused (body would replay in cleartext)");

      // 307/308 HTTPS->HTTP with a body: must throw (guard fires — the
      // body would otherwise be replayed over cleartext).
      assertTrue(
          DefaultApiClient.shouldRefuseHttpsToHttpBodyReplay(origin, target, 307, true),
          "307 HTTPS->HTTP with body must be refused (body would replay in cleartext)");
      assertTrue(
          DefaultApiClient.shouldRefuseHttpsToHttpBodyReplay(origin, target, 308, true),
          "308 HTTPS->HTTP with body must be refused (body would replay in cleartext)");
    }
  }

